SELECT 'batch_019_85f2f0fb_wav_10' AS batch_id,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-04e4f884-8c1','sm-upload-15add848-cb6','sm-upload-8027cffa-3f0','sm-upload-914669ae-daf','sm-upload-baaca575-1e5','sm-upload-c422ca21-bc0','sm-upload-c5006572-e0e','sm-upload-c80b56a6-9cb','sm-upload-e38cb628-82f','sm-upload-e4b4a430-9bf') AND album_id='al-45137ca79f34f6134d6c13be85f2f0fb') AS candidate_masters_in_target,(SELECT COUNT(*) FROM song_masters WHERE id IN ('sm-upload-04e4f884-8c1','sm-upload-15add848-cb6','sm-upload-8027cffa-3f0','sm-upload-914669ae-daf','sm-upload-baaca575-1e5','sm-upload-c422ca21-bc0','sm-upload-c5006572-e0e','sm-upload-c80b56a6-9cb','sm-upload-e38cb628-82f','sm-upload-e4b4a430-9bf') AND album_id='pending-uploads') AS candidate_masters_still_pending,(SELECT COUNT(*) FROM albums WHERE id='al-45137ca79f34f6134d6c13be85f2f0fb' AND name='AI绫') AS target_album_rows,(SELECT song_count FROM albums WHERE id='al-45137ca79f34f6134d6c13be85f2f0fb') AS stored_song_count,(SELECT COALESCE(SUM(si.size),0) FROM song_instances si JOIN song_masters sm ON sm.id=si.master_id WHERE sm.album_id='al-45137ca79f34f6134d6c13be85f2f0fb') AS calculated_size;
